input.command:
node <<'NODE'
const l=JSON.parse(require('fs').readFileSync('package-lock.json','utf8'));
for (const name of ['next','react','react-dom','zod','prisma','@prisma/client','libxmljs2','sharp','tar','jsonwebtoken']) {
 const p=l.packages?.[`node_modules/${name}`];
 console.log(`${name}: ${p?.version ?? 'no presente'}`);
}
NODE

npm pack --dry-run --json --ignore-scripts > auditoria-npm-pack.json && node <<'NODE'
const r=JSON.parse(require('fs').readFileSync('auditoria-npm-pack.json','utf8'))[0];
console.log(JSON.stringify({name:r.name,version:r.version,private:require('./package.json').private,totalFiles:r.files?.length,unpackedSize:r.unpackedSize,sensitiveFiles:(r.files||[]).map(f=>f.path).filter(p=>/(^|\/)(\.env|flag|supplier-registry|.*\.db|.*\.log|auditoria-)/i.test(p))},null,2));
NODE

node <<'NODE'
for (const f of ['auditoria-npm.json','auditoria-npm-produccion.json']) {
 const r=JSON.parse(require('fs').readFileSync(f,'utf8'));
 const urls=new Set(); const bySeverity={};
 for (const v of Object.values(r.vulnerabilities||{})) for (const a of v.via||[]) if (typeof a!=='string'&&a.url) {urls.add(a.url); bySeverity[a.severity]=(bySeverity[a.severity]||0)+1;}
 console.log(f, 'avisos únicos:', urls.size, 'referencias por severidad (avisos pueden repetirse entre paquetes):', bySeverity);
}
